static std::string str_to_std_string(Str s) {
    return std::string(s.ptr, s.len);
}

static Str stash_owned_string(std::deque<std::string>& store, const std::string& value) {
    store.push_back(value);
    const auto& kept = store.back();
    return {kept.c_str(), static_cast<u32>(kept.size())};
}

#if RUT_VALIDATE_REGEX_WITH_VECTORSCAN
static bool validate_regex_literal(Str pattern, std::string* error) {
    std::string wrapped;
    wrapped.reserve(static_cast<size_t>(pattern.len) + 7);
    wrapped.append("^(?:", 4);
    wrapped.append(pattern.ptr, pattern.len);
    wrapped.append(")$", 2);

    hs_database_t* db = nullptr;
    hs_compile_error_t* compile_error = nullptr;
    const hs_error_t rc = hs_compile(
        wrapped.c_str(), HS_FLAG_SINGLEMATCH, HS_MODE_BLOCK, nullptr, &db, &compile_error);
    if (rc == HS_SUCCESS && db) {
        hs_free_database(db);
        return true;
    }
    if (compile_error && compile_error->message) {
        *error = compile_error->message;
    } else {
        *error = "regex compilation failed";
    }
    if (compile_error) hs_free_compile_error(compile_error);
    if (db) hs_free_database(db);
    return false;
}
#endif

static bool type_shape_is_simple_importable(const HirTypeKind type,
                                            u32 variant_index,
                                            u32 struct_index,
                                            u32 tuple_len,
                                            const HirTypeKind* tuple_types,
                                            const u32* tuple_variant_indices,
                                            const u32* tuple_struct_indices) {
    switch (type) {
        case HirTypeKind::Bool:
        case HirTypeKind::I32:
        case HirTypeKind::Str:
        case HirTypeKind::Generic:
        case HirTypeKind::Unknown:
            return true;
        case HirTypeKind::Struct:
            return struct_index != 0xffffffffu;
        case HirTypeKind::Variant:
            return variant_index != 0xffffffffu;
        case HirTypeKind::Tuple:
            for (u32 i = 0; i < tuple_len; i++) {
                if (tuple_types[i] == HirTypeKind::Struct && tuple_struct_indices[i] != 0xffffffffu)
                    continue;
                if (tuple_types[i] == HirTypeKind::Variant &&
                    tuple_variant_indices[i] != 0xffffffffu)
                    continue;
                if (!type_shape_is_simple_importable(tuple_types[i],
                                                     tuple_variant_indices[i],
                                                     tuple_struct_indices[i],
                                                     0,
                                                     nullptr,
                                                     nullptr,
                                                     nullptr))
                    return false;
            }
            return true;
        default:
            return false;
    }
}

enum class TextFileReadStatus : u8 { Ok, Failed, SourceLimit };

static TextFileReadStatus read_text_file(const std::filesystem::path& path,
                                         std::string& out,
                                         SourceBudget* source_budget) {
    std::ifstream in(path, std::ios::binary);
    if (!in) return TextFileReadStatus::Failed;
    in.seekg(0, std::ios::end);
    const std::streamoff size = in.tellg();
    if (size < 0) return TextFileReadStatus::Failed;
    if (source_budget != nullptr &&
        (source_budget->used_bytes > source_budget->max_bytes ||
         static_cast<u64>(size) > source_budget->max_bytes - source_budget->used_bytes)) {
        source_budget->exceeded = true;
        return TextFileReadStatus::SourceLimit;
    }
    in.seekg(0, std::ios::beg);
    out.resize(static_cast<size_t>(size));
    if (size != 0 && !in.read(out.data(), size)) return TextFileReadStatus::Failed;
    if (source_budget != nullptr) source_budget->used_bytes += static_cast<u64>(size);
    return TextFileReadStatus::Ok;
}

static bool same_type_shape_node(const HirTypeShape& lhs, const HirTypeShape& rhs) {
    if (lhs.type != rhs.type) return false;
    if (lhs.generic_index != rhs.generic_index) return false;
    if (lhs.variant_index != rhs.variant_index) return false;
    if (lhs.struct_index != rhs.struct_index) return false;
    if (lhs.tuple_len != rhs.tuple_len) return false;
    for (u32 i = 0; i < lhs.tuple_len; i++) {
        if (lhs.tuple_elem_shape_indices[i] != rhs.tuple_elem_shape_indices[i]) return false;
    }
    if (lhs.array_elem_shape_index != rhs.array_elem_shape_index) return false;
    return true;
}

static FrontendResult<u32> intern_hir_type_shape(HirModule* mod,
                                                 HirTypeKind type,
                                                 u32 generic_index,
                                                 u32 variant_index,
                                                 u32 struct_index,
                                                 u32 tuple_len,
                                                 const HirTypeKind* tuple_types,
                                                 const u32* tuple_variant_indices,
                                                 const u32* tuple_struct_indices,
                                                 Span span,
                                                 u32 array_elem_shape_index = 0xffffffffu) {
    // Normalize: HirExpr's variant_index defaults to 0 (not the 0xffffffffu
    // sentinel), so callers that pass `out.variant_index` for a non-Variant
    // type accidentally poison dedup. Force the index fields to sentinel
    // for any kind that doesn't actually carry them. Same for struct/generic.
    if (type != HirTypeKind::Variant) variant_index = 0xffffffffu;
    if (type != HirTypeKind::Struct) struct_index = 0xffffffffu;
    if (type != HirTypeKind::Generic) generic_index = 0xffffffffu;
    HirTypeShape shape{};
    shape.type = type;
    shape.generic_index = generic_index;
    shape.variant_index = variant_index;
    shape.struct_index = struct_index;
    shape.tuple_len = tuple_len;
    shape.array_elem_shape_index =
        type == HirTypeKind::Array ? array_elem_shape_index : 0xffffffffu;
    shape.is_concrete = type == HirTypeKind::Bool || type == HirTypeKind::I32 ||
                        type == HirTypeKind::I64 || type == HirTypeKind::Str ||
                        type == HirTypeKind::Method || type == HirTypeKind::ByteSize ||
                        type == HirTypeKind::IP || type == HirTypeKind::Response;
    if (type == HirTypeKind::Variant) shape.is_concrete = variant_index != 0xffffffffu;
    if (type == HirTypeKind::Struct) shape.is_concrete = struct_index != 0xffffffffu;
    if (type == HirTypeKind::Array) {
        // Array is concrete iff its element shape is concrete and the element
        // shape is actually resolved. Element shape is already interned (the
        // caller passed array_elem_shape_index), so just look it up.
        shape.is_concrete = array_elem_shape_index < mod->type_shapes.len &&
                            mod->type_shapes[array_elem_shape_index].is_concrete;
    }
    if (type == HirTypeKind::Tuple) {
        shape.is_concrete = true;
        for (u32 i = 0; i < tuple_len; i++) {
            const auto elem_type = tuple_types[i];
            const u32 elem_generic_index =
                elem_type == HirTypeKind::Generic ? tuple_struct_indices[i] : 0xffffffffu;
            const u32 elem_variant_index =
                elem_type == HirTypeKind::Variant ? tuple_variant_indices[i] : 0xffffffffu;
            const u32 elem_struct_index =
                elem_type == HirTypeKind::Struct ? tuple_struct_indices[i] : 0xffffffffu;
            auto elem_shape = intern_hir_type_shape(mod,
                                                    elem_type,
                                                    elem_generic_index,
                                                    elem_variant_index,
                                                    elem_struct_index,
                                                    0,
                                                    nullptr,
                                                    nullptr,
                                                    nullptr,
                                                    span);
            if (!elem_shape) return core::make_unexpected(elem_shape.error());
            shape.tuple_elem_shape_indices[i] = elem_shape.value();
            if (!mod->type_shapes[elem_shape.value()].is_concrete) shape.is_concrete = false;
        }
    }
    for (u32 i = 0; i < mod->type_shapes.len; i++) {
        if (same_type_shape_node(mod->type_shapes[i], shape)) return i;
    }
    if (!mod->type_shapes.push(shape)) return frontend_error(FrontendError::TooManyItems, span);
    return mod->type_shapes.len - 1;
}

